entries[12827] = { ["name"] = "Plans: Serenity", ["text"] = "Use: Teaches you how to make Serenity.\nRequires Classic Blacksmithing (285)\nSell Price:\nSerenity\nBinds when equipped\nOne-Hand Mace\n4 - 6 Damage Speed 2.60\n(1.9 damage per second)\nDurability 90 / 90\nChance on hit: Dispels a magic effect on the current foe.\nSell Price:\nRequires Enchanted Thorium Bar (6), Arcanite Bar (2), Powerful Mojo (4), Large Opal (2), Blue Sapphire (2), Huge Emerald" }
entries[12828] = { ["name"] = "Plans: Volcanic Hammer", ["text"] = "Use: Teaches you how to make a Volcanic Hammer.\nRequires Classic Blacksmithing (290)\nSell Price:\nVolcanic Hammer\nBinds when equipped\nOne-Hand Mace\n4 - 6 Damage Speed 2.60\n(1.9 damage per second)\nDurability 75 / 75\nChance on hit: Hurls a fiery ball that causes 2 Fire damage and an additional 0 damage over 6 sec.\nSell Price:\nRequires Thorium Bar (30), Heart of Fire (4), Star Ruby (4), Rugged Leather (4)" }
