entries[12830] = { ["name"] = "Plans: Corruption", ["text"] = "Use: Teaches you how to make Corruption.\nRequires Classic Blacksmithing (290)\nSell Price:\nCorruption\nBinds when picked up\nTwo-Hand Sword\n6 - 11 Damage Speed 3.60\n(2.4 damage per second)\n+6 Strength\n+6 Stamina\nDurability 100 / 100\nSell Price:\nRequires Thorium Bar (40), Arcanite Bar (2), Demonic Rune (16), Essence of Undeath (8), Blue Sapphire (2), Dense Grinding Stone (2), Rugged Leather (4)" }
entries[12831] = { ["name"] = "Plans: Blood Talon", ["text"] = "Use: Teaches you how to make Blood Talon.\nRequires Classic Blacksmithing (300)\nSell Price:\nBlood Talon\nBinds when picked up\nOne-Hand Fist Weapon\n4 - 6 Damage Speed 2.60\n(1.9 damage per second)\nChance on hit: Your melee attacks have a chance to cause the target to bleed for 19 damage over 30 sec.\nSell Price:\nRequires Enchanted Thorium Bar (10), Arcanite Bar (10), Demonic Rune (8), Star Ruby (10), Dense Grinding Stone (2)" }
entries[12832] = { ["name"] = "Plans: Darkspear", ["text"] = "Use: Teaches you how to make a Darkspear.\nRequires Classic Blacksmithing (300)\nSell Price:\nDarkspear\nBinds when equipped\nTwo-Hand Polearm\n6 - 13 Damage Speed 3.60\n(2.6 damage per second)\nDurability 100 / 100\nChance on hit: Party members have a chance to increase their critical strike by 17 . Lasts for 20 sec.\nSell Price:\nRequires Enchanted Thorium Bar (20), Powerful Mojo (20), Huge Emerald (2), Azerothian Diamond (2), Dense Grinding Stone (2)" }
entries[12833] = { ["name"] = "Plans: Hammer of the Titans", ["text"] = "Use: Teaches you how to make a Hammer of the Titans.\nRequires Classic Blacksmithing (300)\nSell Price:\nHammer of the Titans\nBinds when equipped\nTwo-Hand Mace\n8 - 11 Damage Speed 3.60\n(2.6 damage per second)\n+3 Strength\nDurability 100 / 100\nChance on hit: Stuns target for 3 sec.\nSell Price:\nRequires Thorium Bar (50), Arcanite Bar (15), Guardian Stone (4), Enchanted Leather (6), Essence of Earth (10)" }
entries[12834] = { ["name"] = "Plans: Arcanite Champion", ["text"] = "Use: Teaches you how to make an Arcanite Champion.\nRequires Classic Blacksmithing (300)\nSell Price:\nArcanite Champion\nBinds when equipped\nTwo-Hand Sword\n7 - 12 Damage Speed 3.60\n(2.6 damage per second)\nDurability 100 / 100\nChance on hit: Heal self for 6 and increases Strength by 2 for 30 sec.\nSell Price:\nRequires Arcanite Bar (15), Azerothian Diamond (8), Righteous Orb , Large Opal (4), Enchanted Leather (8), Dense Grinding Stone (2)" }
entries[12835] = { ["name"] = "Plans: Annihilator", ["text"] = "Use: Teaches you how to make an Annihilator.\nRequires Classic Blacksmithing (300)\nSell Price:\nAnnihilator\nBinds when equipped\nOne-Hand Axe\n3 - 7 Damage Speed 2.60\n(1.9 damage per second)\nDurability 90 / 90\nChance on hit: Reduces an enemy's armor by 38 . Stacks up to 3 times.\nSell Price:\nRequires Thorium Bar (40), Arcanite Bar (12), Essence of Undeath (10), Huge Emerald (8), Dense Grinding Stone (2), Enchanted Leather (4)" }
entries[12836] = { ["name"] = "Plans: Frostguard", ["text"] = "Use: Teaches you how to make a Frostguard.\nRequires Classic Blacksmithing (300)\nSell Price:\nFrostguard\nBinds when equipped\nOne-Hand Sword\n3 - 7 Damage Speed 2.60\n(1.9 damage per second)\nDurability 90 / 90\nChance on hit: Target's movement slowed by 30% and increasing the time between attacks by 25% for 5 sec.\nSell Price:\nRequires Arcanite Bar (18), Blue Sapphire (8), Azerothian Diamond (8), Essence of Water (4), Dense Grinding Stone (2), Enchanted Leather (4)" }
entries[12837] = { ["name"] = "Plans: Masterwork Stormhammer", ["text"] = "Binds when picked up\nUse: Teaches you how to make a Masterwork Stormhammer.\nRequires Classic Blacksmithing (300)\nSell Price:\nMasterwork Stormhammer\nBinds when equipped\nOne-Hand Mace\n4 - 6 Damage Speed 2.60\n(1.9 damage per second)\nDurability 90 / 90\nChance on hit: Blasts up to 3 targets for 2 Nature damage.\nSell Price:\nRequires Enchanted Thorium Bar (20), Huge Emerald (8), Large Opal (8), Essence of Earth (6), Enchanted Leather (4)" }
